B.aqT=new A.bv("kanun_09",B.eH,"B\xf6lge adliye mahkemesi hukuk dairelerinden verilen a\u015fa\u011f\u0131daki kararlardan hangisine kar\u015f\u0131 kural olarak temyiz yoluna ba\u015fvurulamaz?",B.ai7,2,"HMK m. 362/1-\xe7 bendine g\xf6re \xe7eki\u015fmesiz yarg\u0131 i\u015flerinde verilen b\xf6lge adliye mahkemesi kararlar\u0131 kesin olup bu kararlara kar\u015f\u0131 temyiz yoluna ba\u015fvurulamaz.")
B.aem=s(["Feragat, h\xfck\xfcm kesinle\u015finceye kadar her zaman yap\u0131labilir.","Feragatin ge\xe7erlili\u011fi kar\u015f\u0131 taraf\u0131n veya mahkemenin kabul\xfcne ba\u011fl\u0131d\u0131r.","Feragat, kesin h\xfck\xfcm gibi hukuki sonu\xe7 do\u011furur.","\u015earta ba\u011fl\u0131 feragat kural olarak ge\xe7erli de\u011fildir."],t.s)
B.aqu=new A.bv("taraf_08",B.eG,'Davac\u0131n\u0131n talep sonucundan k\u0131smen veya tamamen vazge\xe7mesi olan "feragat" kurumu ile ilgili a\u015fa\u011f\u0131dakilerden hangisi yanl\u0131\u015ft\u0131r?',B.aem,1,"HMK m. 309 uyar\u0131nca feragat ve kabul, kar\u015f\u0131 taraf\u0131n veya mahkemenin muvafakatine ba\u011fl\u0131 de\u011fildir; tek tarafl\u0131 irade beyan\u0131yla derhal sonu\xe7 do\u011furur.")
